'use strict';
const $ = (id) => document.getElementById(id);
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={book:'<path d="M4 4h7a3 3 0 0 1 3 3v14a4 4 0 0 0-4-3H4z"/><path d="M20 4h-4a3 3 0 0 0-2 3v14a4 4 0 0 1 4-3h2z"/>',code:'<path d="m8 6-6 6 6 6m8-12 6 6-6 6M14 3l-4 18"/>',tree:'<rect x="8" y="2" width="8" height="5" rx="1"/><path d="M12 7v5M4 16v-4h16v4"/><rect x="1" y="16" width="6" height="5" rx="1"/><rect x="17" y="16" width="6" height="5" rx="1"/>',tail:'<path d="M18 7a7 7 0 1 0 1 9M18 2v6h-6"/>',files:'<path d="M14 2H5v20h14V7zM14 2v5h5M8 12h8M8 16h8"/>',play:'<path d="m8 4 12 8-12 8z"/>',pause:'<path d="M8 4v16M16 4v16"/>',prev:'<path d="m15 5-7 7 7 7"/>',next:'<path d="m9 5 7 7-7 7"/>',first:'<path d="M5 5v14m14-14-9 7 9 7"/>',last:'<path d="M19 5v14M5 5l9 7-9 7"/>',check:'<path d="m5 12 4 4L19 6"/>',bulb:'<path d="M8 17h8m-7 4h6M8 14a7 7 0 1 1 8 0v3H8z"/>',download:'<path d="M12 2v13m-5-5 5 5 5-5M4 18v4h16v-4"/>',open:'<path d="M13 3h8v8m0-8L11 13M9 3H3v18h18v-6"/>',save:'<path d="M4 3h14l3 3v15H3V3zM7 3v6h10V3M7 21v-8h10v8"/>'};
function icon(name){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.code}</svg>`;}
let catalog,health;
let storageWarning=false;
let saved={drafts:{},explore:{},completed:{},last:'tp1-08'};
try{const data=JSON.parse(localStorage.getItem('prolog-lab-v1')||'null');if(data&&typeof data==='object'){for(const key of ['drafts','explore','completed'])if(data[key]&&typeof data[key]==='object')saved[key]=data[key];if(typeof data.last==='string')saved.last=data.last;}}catch{storageWarning=true;}
const state={view:'practicos',group:'tp1',id:saved.last,mode:'explore',visual:'tree',result:null,cursor:0,selected:null,playing:false,speed:650,busy:false,checking:false,hints:0,variant:0,checks:null};
let timer=null,saveTimer=null,toastTimer=null,requestToken=0;
const groups={tp1:'Práctico 1',tp2:'Práctico 2 · problemas',control:'Recursión y corte',tail:'Recursión de cola',conceptos:'Conceptos'};
const ports={call:{name:'Llamada',color:'#347baa',fill:'#eef6fc',text:'Prolog entra a este objetivo y busca una cláusula cuya cabeza pueda unificar.'},unify:{name:'Unificación',color:'#07806e',fill:'#e6f6ef',text:'La cabeza de esta cláusula unifica con la llamada. Se comparten sus variables y se ejecuta el cuerpo de izquierda a derecha.'},exit:{name:'Éxito',color:'#3f9165',fill:'#eaf7ef',text:'Este objetivo tiene una solución. Puede conservar alternativas para un próximo retroceso.'},redo:{name:'Retroceso',color:'#b98225',fill:'#fff4df',text:'Prolog deshace las ligaduras posteriores al punto de elección y retoma la búsqueda de otra alternativa.'},fail:{name:'Fallo',color:'#c65d69',fill:'#fff0f2',text:'Este objetivo agotó sus alternativas. Si ya produjo soluciones, esto indica que no quedan más; no invalida las respuestas anteriores.'},cut:{name:'Corte',color:'#8263b3',fill:'#f3edfc',text:'Se encontró !. El corte fija la cláusula elegida y las elecciones hechas a su izquierda dentro de esta llamada.'},cut_done:{name:'Corte ejecutado',color:'#8263b3',fill:'#f3edfc',text:'Se eliminaron los puntos de elección alcanzados por este corte. Los objetivos a su derecha pueden seguir teniendo alternativas.'},exception:{name:'Error',color:'#c65d69',fill:'#fff0f2',text:'Se produjo una excepción. Revisá el mensaje del intérprete y los argumentos de esta llamada.'}};
function current(){return catalog.exercises.find(e=>e.id===state.id)||catalog.exercises[0];}
function persist(){try{localStorage.setItem('prolog-lab-v1',JSON.stringify(saved));return true;}catch{if(!storageWarning){toast('El navegador no permite guardar. Podés descargar tu código.');storageWarning=true;}return false;}}
function toast(text){$('toast').textContent=text;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3500);}
function stop(){clearInterval(timer);timer=null;state.playing=false;}
function invalidate(){requestToken++;stop();state.result=null;state.checks=null;state.hints=0;state.cursor=0;state.selected=null;state.variant=0;state.busy=false;state.checking=false;}
function snapshot(){if(!$('code'))return;const data={code:$('code').value,query:$('query').value,variant:state.variant};if(state.view==='laboratorio')saved.free=data;else {(state.mode==='practice'?saved.drafts:saved.explore)[state.id]=data;saved.last=state.id;}persist();}
function codeData(){if(state.view==='laboratorio')return saved.free||{code:'padre(juan,ana).\npadre(ana,luis).\n\nancestro(X,Y) :- padre(X,Y).\nancestro(X,Y) :- padre(X,Z), ancestro(Z,Y).\n',query:'ancestro(juan,Y).'};const e=current();return (state.mode==='practice'?saved.drafts:saved.explore)[e.id]||{code:state.mode==='practice'?e.starter:e.solution,query:e.queries[0]};}
function countCompleted(){return catalog.exercises.filter(e=>saved.completed[e.id]).length;}
function render(){ PrologEditor.close(false);
 stop();const e=current();const complete=countCompleted();const navs=[['practicos','book','Prácticos'],['laboratorio','code','Laboratorio libre'],['tail','tail','Recursión de cola'],['conceptos','tree','Conceptos'],['biblioteca','files','Material de cátedra']];
 $('app').innerHTML=`<div class="app-shell"><aside class="sidebar"><div class="brand"><div class="brand-mark">?-</div><div><div class="brand-name">prolog<span style="color:#65d5ba">lab</span></div><small>Programación III</small></div></div><div class="nav-label">Tu espacio de estudio</div><nav aria-label="Secciones">${navs.map(([id,ic,label])=>`<button class="nav-item ${state.view===id?'active':''}" data-nav="${id}" ${state.view===id?'aria-current="page"':''}>${icon(ic)}<span>${label}</span>${state.view===id?'<i class="nav-dot"></i>':''}</button>`).join('')}</nav><div class="sidebar-footer"><div class="progress-top"><span>Tu recorrido</span><b id="progress-number">${complete}/${catalog.exercises.length}</b></div><div class="progress-bar"><span id="progress-fill" style="width:${complete/catalog.exercises.length*100}%"></span></div><p>Se completa una actividad al superar sus comprobaciones.</p><div class="engine-tag"><span></span>${health.ok?'SWI-Prolog · listo':'Motor no disponible'}</div></div></aside><main class="main"><div class="topbar"><span><strong>Programación III</strong> &nbsp;/&nbsp; ${esc(navs.find(n=>n[0]===state.view)[2])}</span><span class="local-badge">Guardado en este navegador</span></div>${state.view==='biblioteca'?library():workspacePage(e)}</main></div>`;
 document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>navigate(b.dataset.nav));
 if(state.view!=='biblioteca'){wireEditor();updateVisual();}
}
function heading(title,subtitle,eyebrow='APRENDÉ HACIENDO'){return `<div class="heading"><div><div class="eyebrow">${esc(eyebrow)}</div><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div>${state.view!=='biblioteca'?`<button id="download" class="secondary-button">${icon('download')} Descargar .pl</button>`:''}</div>`;}
function workspacePage(e){
 const free=state.view==='laboratorio',tail=state.view==='tail',concept=state.view==='conceptos';
 const title=free?'Probá tus propias reglas':tail?'Pensá con acumuladores':concept?'Entendé lo que está pasando':'De la regla al árbol';
 const subtitle=free?'Escribí un programa, consultalo y seguí su ejecución.':tail?'Transformá la recursión y observá qué se lleva cada llamada.':concept?'Unificación, aritmética, negación y búsqueda, en acción.':'Los prácticos de tu cátedra, con soluciones y espacio para experimentar.';
 let list=catalog.exercises.filter(x=>x.group===state.group);
 if(tail)list=catalog.exercises.filter(x=>x.group==='tail');if(concept)list=catalog.exercises.filter(x=>x.group==='conceptos');
 return heading(title,subtitle)+(tail?`<div class="tail-banner"><div><h2>El resultado viaja hacia adelante</h2><p>En la versión directa, una operación espera al regreso de la recursión. Con un acumulador, el resultado parcial entra a la siguiente llamada.</p><p>La llamada recursiva queda al final: <code>suma_acc(Xs, A1, S)</code>.</p></div><div><div class="acc-model"><div class="acc-cell"><b>0</b><small>inicio</small></div><span class="acc-separator">›</span><div class="acc-cell"><b>1</b><small>+ 1</small></div><span class="acc-separator">›</span><div class="acc-cell"><b>4</b><small>+ 3</small></div><span class="acc-separator">›</span><div class="acc-cell"><b>9</b><small>+ 5</small></div></div><p class="model-note">Modelo para [1,3,5]. La traza del depurador no mide la memoria optimizada.</p></div></div>`:'')+
 (!free?`${!tail&&!concept?`<div class="course-tabs" role="tablist" aria-label="Guías de prácticos">${['tp1','tp2','control'].map(g=>`<button class="course-tab ${state.group===g?'active':''}" data-group="${g}" role="tab" aria-selected="${state.group===g}">${groups[g]}<span>${g==='control'?'3':catalog.exercises.filter(x=>x.group===g).length}</span></button>`).join('')}</div>`:''}${tail?`<div class="tail-links">${list.map(x=>`<button data-exercise="${x.id}" class="${x.id===state.id?'active':''}">${esc(x.title)}</button>`).join('')}</div>`:''}<div class="selection-row"><button id="previous-exercise" class="icon-button" aria-label="Actividad anterior" ${list[0]?.id===e.id?'disabled':''}>${icon('prev')}</button><select id="exercise-select" aria-label="Elegir actividad">${list.map(x=>`<option value="${x.id}" ${x.id===e.id?'selected':''}>${esc(x.number)} · ${esc(x.title)}${saved.completed[x.id]?' ✓':''}</option>`).join('')}</select><button id="next-exercise" class="icon-button" aria-label="Actividad siguiente" ${list.at(-1)?.id===e.id?'disabled':''}>${icon('next')}</button><span class="topic-pill">${esc(e.topic)}</span></div><section class="exercise-brief"><div class="exercise-number">${esc(e.number)}</div><div class="brief-body"><h2>${esc(e.title)}</h2><p>${esc(e.statement)}</p><a href="/material/${encodeURIComponent(e.source)}#page=${e.page}" target="_blank" rel="noopener">Ver ${tail||concept?'apunte de referencia':'enunciado original'} · pág. ${e.page}</a></div>${saved.completed[e.id]?'<span class="completed-stamp">Comprobado ✓</span>':''}</section>`:`<div class="free-intro">Podés usar hechos, reglas, listas, corte, aritmética y metapredicados. Las consultas se ejecutan en procesos independientes. Los límites de tiempo e inferencias permiten recuperar el control si una regla entra en un bucle.</div>`)+
 `<div class="workspace"><div><section class="card"><div class="card-header"><h3>${icon('code')} ${free?'Tu programa':'Programa'}</h3>${free?'<small>SWI-Prolog</small>':`<div class="mode-toggle" role="group" aria-label="Modo de estudio"><button id="mode-explore" class="${state.mode==='explore'?'active':''}" aria-pressed="${state.mode==='explore'}">Explorar solución</button><button id="mode-practice" class="${state.mode==='practice'?'active':''}" aria-pressed="${state.mode==='practice'}">Resolver yo</button></div>`}</div><div id="editor-content"><div class="editor-top"><span>${free?'mi_programa':esc(e.id)}.pl</span>${!free&&e.variants.length?`<select id="variant-select" aria-label="Versión del programa" ${state.mode==='practice'?'disabled':''}><option value="0">Solución principal</option>${e.variants.map((v,i)=>`<option value="${i+1}">${esc(v.label)}</option>`).join('')}</select>`:'<span>hechos · reglas · consulta</span>'}</div><div class="editor-wrap"><div class="line-numbers" id="line-numbers" aria-hidden="true"></div><textarea id="code" class="code" aria-label="Editor de código Prolog" spellcheck="false" autocapitalize="off" autocorrect="off" wrap="off"></textarea></div><div class="editor-bottom"><span>Prolog &nbsp; UTF-8</span><div class="editor-status"><span id="saved-state">Borrador local</span><button id="expand-editor" class="expand-editor-button" aria-label="Ampliar editor" aria-haspopup="dialog" aria-controls="editor-dialog" aria-expanded="false"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5"/></svg><span>Ampliar</span></button></div></div><div class="query-area"><div class="field-label"><label for="query">CONSULTA</label>${!free?`<select id="query-examples" aria-label="Cargar una consulta de ejemplo"><option value="">Consultas del ejercicio</option>${e.queries.map((q,i)=>`<option value="${i}">${esc(q)}</option>`).join('')}</select>`:''}</div><div class="query-input"><span>?-</span><input id="query" aria-label="Consulta Prolog" spellcheck="false" autocapitalize="off"></div><div class="run-actions"><button id="run" class="primary-button">${icon('play')} Ejecutar y dibujar</button>${!free?`<button id="check" class="secondary-button">${icon('check')} Comprobar</button>`:''}<span class="editor-help">Ctrl + Enter</span></div></div></div></section>${!free?`<section class="card study-tools"><div class="card-header"><h3>${icon('bulb')} Una ayuda, si la necesitás</h3></div><div class="tool-buttons"><button id="hint" class="small-button">Ver una pista</button><button id="solution" class="small-button">Ver solución explicada</button><button id="reset" class="small-button">Restablecer código</button><button id="undo-reset" class="small-button" hidden>Deshacer</button></div><div id="hints" class="hint-area" hidden></div><div id="checks" class="check-results" aria-live="polite"></div>${tail?'<p class="tail-check-note">Las pruebas verifican resultados. También analizamos la posición de las llamadas recursivas directas en tu código.</p>':''}</section>`:''}<p class="footer-note">Tus cambios se guardan automáticamente. El código de exploración y tu solución propia se conservan por separado.</p></div><div><section class="card answers-card"><div class="card-header"><h3>Respuestas</h3><small id="answer-status">Esperando una consulta</small></div><div id="answers" class="answers-content" aria-live="polite"><p style="font-size:13px;color:var(--muted)">Ejecutá una consulta para obtener sus soluciones.</p></div></section><section class="card"><div class="visual-header" role="tablist" aria-label="Visualización"><button id="view-tree" role="tab" class="${state.visual==='tree'?'active':''}" aria-selected="${state.visual==='tree'}">Árbol de ejecución</button><button id="view-trace" role="tab" class="${state.visual==='trace'?'active':''}" aria-selected="${state.visual==='trace'}">Traza</button><button id="view-explanation" role="tab" class="${state.visual==='explanation'?'active':''}" aria-selected="${state.visual==='explanation'}">Explicación</button></div><div id="visual"></div></section></div></div>`;
}
function library(){return heading('Tu cátedra, a mano','Los 11 documentos distintos de esta carpeta.','MATERIAL DE ESTUDIO')+`<div class="material-grid">${catalog.materials.map(m=>`<article class="material-card"><div class="pdf-icon">PDF</div><h2>${esc(m.title)}</h2><p>${esc(m.description)}</p><small>${m.pages} ${m.pages===1?'página':'páginas'} · ${esc(m.file)}</small><a href="/material/${encodeURIComponent(m.file)}" target="_blank" rel="noopener">Abrir documento</a></article>`).join('')}</div><p class="library-note">Los archivos duplicados se conservan en la carpeta original. Las soluciones incluyen los 14 ejercicios del Práctico 1, los 8 problemas del Práctico 2 y los 3 ejercicios de la guía de recursión y corte, con sus subapartados.</p>`;}
function navigate(view){snapshot();invalidate();state.view=view;if(view==='practicos'){state.group=['tp1','tp2','control'].includes(current().group)?current().group:'tp1';if(current().group!==state.group)state.id=catalog.exercises.find(e=>e.group===state.group).id;}if(view==='tail'||view==='conceptos'){state.group=view;if(current().group!==view)state.id=catalog.exercises.find(e=>e.group===view).id;}render();}
function choose(id){snapshot();invalidate();state.id=id;state.group=current().group;saved.last=id;persist();render();}
function wireEditor(){ PrologEditor.bind();
 const data=codeData();state.variant=data.variant||0;$('code').value=data.code;$('query').value=data.query;if($('variant-select'))$('variant-select').value=String(state.variant);lines();
 const onEdit=()=>{state.checks=null;if($('checks'))$('checks').innerHTML='';if(state.checking){requestToken++;state.checking=false;$('check').disabled=false;$('check').innerHTML=icon('check')+' Comprobar';}if(state.view!=='laboratorio'){delete saved.completed[state.id];document.querySelector('.completed-stamp')?.remove();}if($('progress-number')){$('progress-number').textContent=countCompleted()+'/'+catalog.exercises.length;$('progress-fill').style.width=countCompleted()/catalog.exercises.length*100+'%';}clearTimeout(saveTimer);saveTimer=setTimeout(()=>{snapshot();$('saved-state').textContent=storageWarning?'Guardado no disponible':'Guardado ✓';},450);lines();};
 $('code').oninput=onEdit;$('query').oninput=()=>{clearTimeout(saveTimer);saveTimer=setTimeout(snapshot,450);};
 $('code').onscroll=()=>{$('line-numbers').scrollTop=$('code').scrollTop;};
 $('code').onkeydown=(event)=>{if(event.key==='Tab'){event.preventDefault();const t=event.target;const p=t.selectionStart;t.setRangeText('    ',p,t.selectionEnd,'end');onEdit();}if(event.key==='Enter'&&(event.ctrlKey||event.metaKey)){event.preventDefault();run();}};
 $('query').onkeydown=(event)=>{if(event.key==='Enter'){event.preventDefault();run();}};
 $('run').onclick=run;$('download').onclick=download;
 if($('mode-explore'))$('mode-explore').onclick=()=>setMode('explore');if($('mode-practice'))$('mode-practice').onclick=()=>setMode('practice');
 if($('variant-select'))$('variant-select').onchange=()=>{const index=Number($('variant-select').value);state.variant=index;$('code').value=index?current().variants[index-1].code:current().solution;state.result=null;state.checks=null;lines();snapshot();renderAnswers();updateVisual();};
 if($('query-examples'))$('query-examples').onchange=()=>{const v=$('query-examples').value;if(v!==''){$('query').value=current().queries[Number(v)];snapshot();$('query-examples').value='';}};
 if($('check'))$('check').onclick=check;
 if($('hint'))$('hint').onclick=()=>{state.hints=Math.min(state.hints+1,current().hints.length);$('hints').hidden=false;$('hints').innerHTML=current().hints.slice(0,state.hints).map((h,i)=>`<p><b>${i+1}.</b> ${esc(h)}</p>`).join('');if(state.hints===current().hints.length)$('hint').disabled=true;};
 if($('solution'))$('solution').onclick=showSolution;
 if($('undo-reset'))$('undo-reset').onclick=()=>{const undo=saved.undo;if(undo?.id===state.id&&undo.mode===state.mode){$('code').value=undo.code;delete saved.undo;lines();snapshot();$('undo-reset').hidden=true;toast('Recuperaste el código anterior.');}};
 if($('reset'))$('reset').onclick=()=>{const previous=$('code').value;const target=state.mode==='practice'?current().starter:current().solution;if(previous===target){toast('El código ya está en su versión inicial.');return;}saved.undo={id:state.id,mode:state.mode,code:previous};$('code').value=target;lines();snapshot();state.checks=null;$('checks').innerHTML='';$('undo-reset').hidden=false;toast('Código restablecido. Podés recuperar tu código con Deshacer.');$('code').focus();};
 if($('exercise-select'))$('exercise-select').onchange=()=>choose($('exercise-select').value);
 const list=catalog.exercises.filter(e=>e.group===state.group),index=list.findIndex(e=>e.id===state.id);
 if($('previous-exercise'))$('previous-exercise').onclick=()=>{if(index>0)choose(list[index-1].id);};if($('next-exercise'))$('next-exercise').onclick=()=>{if(index<list.length-1)choose(list[index+1].id);};
 document.querySelectorAll('[data-group]').forEach(b=>b.onclick=()=>choose(catalog.exercises.find(e=>e.group===b.dataset.group).id));
 document.querySelectorAll('[data-exercise]').forEach(b=>b.onclick=()=>choose(b.dataset.exercise));
 for(const tab of ['tree','trace','explanation'])$(`view-${tab}`).onclick=()=>{stop();state.visual=tab;updateVisual();};
}
function setMode(mode){if(state.mode===mode)return;snapshot();invalidate();state.mode=mode;render();}
function lines(line=0){if(!$('code'))return;const n=$('code').value.split('\n').length;$('line-numbers').innerHTML=Array.from({length:n},(_,i)=>`<span class="line ${i+1===line?'active-line':''}">${i+1}</span>`).join('');$('line-numbers').scrollTop=$('code').scrollTop;}
async function api(code,query,trace=true){return PrologRuntime.run(code,query,trace);}
async function run(){if(state.busy||state.checking)return;const expanded=PrologEditor.expanded;PrologEditor.close(false);snapshot();stop();const code=$('code').value,query=$('query').value;if(!query.trim()){toast('Escribí una consulta para ejecutar.');$('query').focus();return;}const token=++requestToken;state.busy=true;state.result=null;state.selected=null;state.cursor=0;$('run').disabled=true;$('run').innerHTML='<span class="spinner"></span> Ejecutando…';$('answer-status').textContent='Buscando soluciones…';$('answers').innerHTML='<p style="font-size:13px;color:var(--muted)">Ejecutando tu programa con SWI-Prolog…</p>';updateVisual();const r=await api(code,query);if(token!==requestToken)return;state.busy=false;state.result=r;state.cursor=r.events?.length?0:0;state.runCode=code;state.runQuery=query;$('run').disabled=false;$('run').innerHTML=icon('play')+' Ejecutar y dibujar';renderAnswers();updateVisual();if(expanded)$('answers').scrollIntoView({block:'nearest'});}
function errorHelp(error){if(/instantiat|sufficiently/i.test(error))return 'Una operación necesita un valor todavía libre. Ligá las variables antes de usar is, > o =:=.';if(/syntax|Operator expected/i.test(error))return 'Revisá el punto final de cada cláusula, las comas, los paréntesis y los corchetes.';if(/exist|Unknown procedure/i.test(error))return 'Comprobá el nombre del predicado y su cantidad de argumentos. Cada consulta usa solo el programa del editor.';if(/permission|sandbox/i.test(error))return 'Este laboratorio permite cómputo y salida de texto. Las operaciones sobre archivos, procesos o el estado del intérprete están deshabilitadas.';if(/limit|tiempo|inferenci/i.test(error))return 'Revisá el caso base y que la llamada recursiva avance hacia él. También podés reducir el tamaño de la entrada.';return 'Podés revisar la traza hasta el punto del error y volver a intentar.';}
function renderAnswers(){const r=state.result;if(!r){$('answer-status').textContent='Esperando una consulta';$('answers').innerHTML='<p style="font-size:13px;color:var(--muted)">Ejecutá una consulta para obtener sus soluciones.</p>';return;}if(!r.ok){$('answer-status').textContent='Revisá la consulta';$('answers').innerHTML=`<div class="error-box">${esc(r.error)}</div><p class="error-help">${esc(errorHelp(r.error||''))}</p>`;return;}const n=r.answers.length;$('answer-status').textContent=`${n} ${n===1?'solución':'soluciones'}`;$('answers').innerHTML=`<div class="answers-wrap">${n?r.answers.map(a=>`<code class="answer">${esc(a.text)}</code>`).join(''):'<code class="answer false">false</code>'}</div><p class="answer-meta">${r.limited?'Mostrando las primeras 30 soluciones. Hay más alternativas.':'Búsqueda de respuestas completada.'} ${r.traceTruncated?'Traza recortada a 2200 eventos.':''}</p>${r.output?`<pre class="console">${esc(r.output)}</pre>`:''}`;}
function download(){const blob=new Blob([$ ('code').value],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=(state.view==='laboratorio'?'mi_programa':state.id)+'.pl';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Programa descargado.');}
function showSolution(){const e=current();const show=(i)=>{$('solution-content').innerHTML=`${e.variants.length?`<select id="dialog-variant" class="dialog-variant" aria-label="Versión de la solución"><option value="0">Solución principal</option>${e.variants.map((v,j)=>`<option value="${j+1}" ${i===j+1?'selected':''}>${esc(v.label)}</option>`).join('')}</select>`:''}<pre>${esc(i?e.variants[i-1].code:e.solution)}</pre>${e.explanation.map(p=>`<p>${esc(p)}</p>`).join('')}<p>Tu borrador se conserva al cerrar esta ventana.</p>`;if($('dialog-variant'))$('dialog-variant').onchange=()=>show(Number($('dialog-variant').value));};$('solution-title').textContent=e.title;show(0);$('solution-dialog').showModal();}
$('close-dialog').onclick=()=>$('solution-dialog').close();
function updateVisual(){const oldViewport=$('graph-viewport'),oldScroll=oldViewport?{left:oldViewport.scrollLeft,top:oldViewport.scrollTop}:null;const focused=document.activeElement?.id;for(const tab of ['tree','trace','explanation']){const b=$(`view-${tab}`);if(b){b.classList.toggle('active',state.visual===tab);b.setAttribute('aria-selected',String(state.visual===tab));}}const events=state.result?.events||[];if(state.visual==='explanation'){const e=current();$('visual').innerHTML=`<div class="explanation-panel">${(state.view==='laboratorio'?['Prolog selecciona metas de izquierda a derecha y prueba cláusulas en orden. El árbol muestra las llamadas realmente visitadas.', 'Llamada entra a un objetivo; Unificación muestra la cláusula elegida; Éxito devuelve una solución; Retroceso busca otra; Fallo agota las alternativas.', 'Este es un árbol de llamadas del depurador, no un árbol SLD completo. Las cabezas rechazadas por la indexación no aparecen como ramas. Los nombres A, B… son locales a cada instantánea.']:e.explanation).map(p=>`<p>${esc(p)}</p>`).join('')}<p class="note">Las respuestas corresponden a todas las soluciones buscadas. El árbol y la traza reproducen un evento por paso. Un fallo final puede significar que se agotó la búsqueda después de haber encontrado soluciones.</p></div>`;return;}
 if(!events.length){$('visual').innerHTML=`<div class="empty-state">${icon('tree')}${state.busy?'Construyendo la traza…':'Cada llamada tiene una historia.'}<br>${state.busy?'':'Ejecutá el programa para verla paso a paso.'}</div>`;return;}
 state.cursor=Math.max(0,Math.min(state.cursor,events.length-1));
 const toolbar=`<div class="visual-toolbar"><button id="step-first" class="icon-button" aria-label="Primer paso">${icon('first')}</button><button id="step-prev" class="icon-button" aria-label="Paso anterior" ${state.cursor===0?'disabled':''}>${icon('prev')}</button><button id="step-play" class="icon-button" aria-label="${state.playing?'Pausar':'Reproducir'}">${icon(state.playing?'pause':'play')}</button><button id="step-next" class="icon-button" aria-label="Paso siguiente" ${state.cursor===events.length-1?'disabled':''}>${icon('next')}</button><button id="step-last" class="icon-button" aria-label="Último paso">${icon('last')}</button><span class="step-counter">${state.cursor+1} / ${events.length}</span><select id="speed" aria-label="Velocidad de reproducción"><option value="1100" ${state.speed===1100?'selected':''}>Lenta</option><option value="650" ${state.speed===650?'selected':''}>Normal</option><option value="220" ${state.speed===220?'selected':''}>Rápida</option></select></div><div class="timeline"><input id="timeline" type="range" min="0" max="${events.length-1}" value="${state.cursor}" aria-label="Paso de ejecución"></div>`;
 $('visual').innerHTML=toolbar+(state.visual==='tree'?graph(events):`<div class="trace-list" id="trace-list">${events.map((ev,i)=>{const p=ports[ev.port]||ports.call;return `<button class="trace-row ${i===state.cursor?'active':''}" data-step="${i}"><span>${i+1}</span><span style="color:${p.color}">${esc(p.name)}</span><code>${esc(ev.goal)}</code></button>`;}).join('')}</div>`)+eventDetail(events);
 const step=(n)=>{stop();state.cursor=n;state.selected=null;updateVisual();};$('step-first').onclick=()=>step(0);$('step-prev').onclick=()=>step(state.cursor-1);$('step-next').onclick=()=>step(state.cursor+1);$('step-last').onclick=()=>step(events.length-1);$('timeline').onchange=()=>step(Number($('timeline').value));$('speed').onchange=()=>{state.speed=Number($('speed').value);if(state.playing){stop();play();}};$('step-play').onclick=()=>{if(state.playing){stop();updateVisual();}else play();};
 document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>step(Number(b.dataset.step)));
 document.querySelectorAll('[data-node]').forEach(b=>{const select=()=>{stop();state.selected=Number(b.dataset.node);updateVisual();};b.onclick=select;b.onkeydown=event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();select();}};});
 if($('source-line'))$('source-line').onclick=()=>{if($('code').value!==state.runCode){toast('El editor cambió desde la ejecución. Volvé a ejecutar para ubicar la cláusula.');return;}const n=Number($('source-line').dataset.line);lines(n);$('code').scrollTop=Math.max(0,(n-4)*23);$('line-numbers').scrollTop=$('code').scrollTop;$('code').focus();};
 if(state.visual==='trace'){const row=document.querySelector('.trace-row.active');if(row)$('trace-list').scrollTop=Math.max(0,row.offsetTop-$('trace-list').offsetTop-120);}if(oldScroll&&$('graph-viewport')){$('graph-viewport').scrollLeft=oldScroll.left;$('graph-viewport').scrollTop=oldScroll.top;}if($('graph-viewport')){const vp=$('graph-viewport'),active=vp.querySelector('[data-node="'+(state.selected||events[state.cursor].id)+'"]');if(active){const x=Number(active.dataset.x),y=Number(active.dataset.y);vp.scrollLeft=Math.max(0,x-vp.clientWidth/2);if(y<vp.scrollTop+10||y+72>vp.scrollTop+vp.clientHeight)vp.scrollTop=Math.max(0,y-35);}}if(focused?.startsWith('step-'))$(focused)?.focus({preventScroll:true});
}
function play(){const events=state.result?.events||[];if(!events.length)return;if(state.cursor===events.length-1)state.cursor=0;state.playing=true;state.selected=null;updateVisual();timer=setInterval(()=>{if(state.cursor>=events.length-1){stop();updateVisual();return;}state.cursor++;updateVisual();},state.speed);}
function nodeStates(events){const nodes=new Map();for(const e of events.slice(0,state.cursor+1)){if(!nodes.has(e.id))nodes.set(e.id,{id:e.id,parent:e.parent,initial:e.goal,children:[],success:false});const n=nodes.get(e.id);n.event=e;if(e.port==='exit')n.success=true;}for(const n of nodes.values())if(nodes.has(n.parent)&&n.parent!==n.id)nodes.get(n.parent).children.push(n);return nodes;}
function graph(events){const nodes=nodeStates(events),visible=[...nodes.values()].slice(0,160),ids=new Set(visible.map(n=>n.id));for(const n of visible)n.children=n.children.filter(c=>ids.has(c.id));const roots=visible.filter(n=>!ids.has(n.parent));const W=260,GAP=22,H=72,LEVEL=110;
 const size=(n,seen=new Set())=>{if(seen.has(n.id))return W;seen.add(n.id);n.width=n.children.length?Math.max(W,n.children.reduce((sum,c)=>sum+size(c,seen),0)+GAP*(n.children.length-1)):W;return n.width;};
 roots.forEach(n=>size(n));let offset=Math.max(25,(510-roots.reduce((sum,n)=>sum+n.width+GAP,0)+GAP)/2),maxDepth=0;const layout=(n,x,depth,seen=new Set())=>{if(seen.has(n.id))return;seen.add(n.id);n.x=x+n.width/2;n.y=30+depth*LEVEL;maxDepth=Math.max(maxDepth,depth);let start=x;n.children.forEach(c=>{layout(c,start,depth+1,seen);start+=c.width+GAP;});};roots.forEach(n=>{layout(n,offset,0);offset+=n.width+GAP;});const width=Math.max(510,offset),height=Math.max(340,maxDepth*LEVEL+120);const currentId=state.selected||events[state.cursor].id;
 const edges=visible.flatMap(n=>n.children.map(c=>`<path d="M${n.x} ${n.y+H} C${n.x} ${n.y+H+20},${c.x} ${c.y-20},${c.x} ${c.y}" fill="none" stroke="#bac9d8" stroke-width="1.5"/>`)).join('');
 const elements=visible.map(n=>{const p=n.event.port==='fail'&&n.success?{name:'Sin más alternativas',color:'#728394',fill:'#f0f4f7'}:(ports[n.event.port]||ports.call);let label=n.event.goal;const split=label.length>31?label.lastIndexOf(',',31)+1:0;const lines=label.length>31?[label.slice(0,split>8?split:31),label.slice(split>8?split:31)]:[label];const text=lines.slice(0,2).map((l,i)=>`<text x="${n.x-W/2+12}" y="${n.y+23+i*16}" fill="#263d50" font-family="Consolas,monospace" font-size="13">${esc(l.length>33?l.slice(0,32)+'…':l)}</text>`).join('');const status=n.event.port==='fail'&&n.success?'Sin más alternativas':p.name;return `<g class="graph-node" data-node="${n.id}" data-x="${n.x}" data-y="${n.y}" role="button" tabindex="0" aria-label="${esc(status+': '+label)}"><title>${esc(label+' · '+status)}</title><rect x="${n.x-W/2}" y="${n.y}" width="${W}" height="${H}" rx="7" fill="${p.fill}" stroke="${p.color}" stroke-width="${n.id===currentId?2.7:1}"/>${text}<text x="${n.x-W/2+12}" y="${n.y+H-8}" fill="${p.color}" font-family="Segoe UI,sans-serif" font-size="11">${esc(status)}${n.event.line?' · línea '+n.event.line:''}</text>${n.id===currentId?`<circle cx="${n.x+W/2-11}" cy="${n.y+11}" r="3" fill="${p.color}"/>`:''}</g>`;}).join('');
 return `<div class="graph-viewport" id="graph-viewport"><svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}" aria-label="Árbol de llamadas de Prolog">${edges}${elements}</svg></div><div class="legend">${['call','unify','exit','redo','fail','cut'].map(k=>`<span><i style="background:${ports[k].color}"></i>${ports[k].name}</span>`).join('')}</div><div class="graph-caption">Árbol de llamadas real · ${nodes.size} ${nodes.size===1?'nodo visitado':'nodos visitados'}${nodes.size>160?' · se dibujan los primeros 160':''} · desplazá el panel para explorar</div>`;
}
function eventDetail(events){const now=events[state.cursor],ev=state.selected?[...events.slice(0,state.cursor+1)].reverse().find(e=>e.id===state.selected)||now:now;const p=ports[ev.port]||ports.call;const first=events.find(e=>e.id===ev.id);return `<div class="event-detail"><div class="event-heading"><span class="port-badge" style="color:${p.color};background:${p.fill}">${esc(p.name)}</span>${ev.line?`<button id="source-line" class="small-button" data-line="${ev.line}">Línea ${ev.line}</button>`:`<span>Nodo ${ev.id}</span>`}</div><code class="event-goal">${esc(ev.goal)}</code><p>${esc(p.text)}</p>${first&&first.goal!==ev.goal?`<p><b>Al entrar:</b> <code>${esc(first.goal)}</code><br><b>Ahora:</b> <code>${esc(ev.goal)}</code></p>`:''}${ev.clause?`<div class="clause-detail">${esc(ev.clause)}</div>`:''}</div>`;}
async function check(){if(state.checking||state.busy)return;PrologEditor.close(false);const e=current(),code=$('code').value,token=++requestToken;snapshot();state.checking=true;$('check').disabled=true;$('check').textContent='Comprobando…';const results=[];for(const test of e.tests){const r=await api(code,test.query,false);if(token!==requestToken)return;results.push({...test,passed:r.ok&&r.answers.length>0,error:r.ok?'La consulta de prueba no se cumple.':r.error});$('checks').innerHTML=checksHtml(results,e.tests.length,false);}
 let analysis=[];if(state.view==='tail'){const r=await api(code,e.queries[0],false);if(token!==requestToken)return;analysis=r.analysis||[];}
 state.checking=false;state.checks=results;const outputsPass=results.every(r=>r.passed);const tailPass=state.view!=='tail'||(analysis.some(a=>a.recursive)&&analysis.filter(a=>a.recursive).every(a=>a.tail));
 if(outputsPass&&tailPass)saved.completed[e.id]=true;else delete saved.completed[e.id];persist();$('check').disabled=false;$('check').innerHTML=icon('check')+' Comprobar';$('checks').innerHTML=checksHtml(results,e.tests.length,true)+(analysis.length?`<div class="analysis-pills">${analysis.filter(a=>a.recursive).map(a=>`<span class="${a.tail?'':'non-tail'}">${esc(a.predicate)} · ${a.tail?'de cola':'trabajo al volver'}</span>`).join('')}</div><p class="check-summary">${tailPass?'Las llamadas recursivas directas están en posición de cola.':'Todavía queda trabajo después de una llamada, o no hay recursión directa para analizar.'}</p>`:'');$('progress-number').textContent=`${countCompleted()}/${catalog.exercises.length}`;$('progress-fill').style.width=countCompleted()/catalog.exercises.length*100+'%';toast(outputsPass&&tailPass?'Superaste las comprobaciones de esta actividad.':outputsPass?'Los resultados pasan. Revisá la posición de cola.':'Hay casos para revisar. Mirá el detalle de las pruebas.');}
function checksHtml(results,total,done){return results.map(r=>`<div class="test-row"><span class="test-status ${r.passed?'':'fail'}">${r.passed?'✓':'×'}</span><span>${esc(r.label)}</span><details><summary>Ver consulta${r.passed?'':' y resultado'}</summary><pre>${esc(r.query)}</pre>${r.passed?'':`<p>${esc(r.error)}</p>`}</details></div>`).join('')+`<p class="check-summary">${results.filter(r=>r.passed).length}/${total} casos superados.${done?' Son comprobaciones sobre estos ejemplos; podés seguir probando otras entradas.':' Comprobando…'}</p>`;}
async function init(){try{const responses=await Promise.all([fetch('catalog.json').then(r=>r.json()),PrologRuntime.ready().catch(error=>({ok:false,error:error.message}))]);[catalog,health]=responses;if(!catalog.exercises.some(e=>e.id===state.id))state.id='tp1-08';const g=current().group;if(g==='tail'||g==='conceptos')state.view=g;state.group=g;render();if(!health.ok)toast(health.error||'No se pudo cargar Prolog. Recargá la página para volver a intentar.');if(storageWarning)toast('El guardado local no está disponible. Podés descargar tu código.');if(state.mode==='explore'&&health.ok)run();}catch(e){$('app').innerHTML='<div class="loading"><h1>No se pudo abrir el laboratorio</h1><p>Revisá la conexión a internet y volvé a cargar esta página.</p></div>';}}
window.addEventListener('beforeunload',snapshot);
init();


